server {
    listen 443 ssl;
    server_name example.com;

    ssl_certificate     /etc/ssl/example.crt;   # leaf only, no chain
    ssl_certificate_key /etc/ssl/example.key;

    # "keep old clients working"
    ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:RSA+AES128-SHA;
    ssl_prefer_server_ciphers on;   # we ordered strong suites first

    # no Strict-Transport-Security header
    # plain http:// on port 80 is served by a separate block, no redirect

    location / {
        proxy_pass http://app_upstream;
    }
}
